  const getCardStyle = (itemId, gridArea) => ({
    gridArea,
    backgroundColor: cardBackgroundColor,
    border: `1px solid ${hoveredItem === itemId ? textColor : borderColor}`,
    borderRadius: cornerRadius,
    padding: '20px',
