    justifyContent: 'space-between',
    position: 'relative',
    overflow: 'hidden'
  });

  const labelStyle = {
    fontSize: '11px',
    color: secondaryTextColor,
    fontWeight: '400',
    letterSpacing: '0.02em'
  };

  const renderContent = (item) => {
    switch (item.type) {
      case 'heading':
        return (
          <>
            <div style={labelStyle}>{item.label}</div>
            <div style={{
              fontSize: '32px',
              fontWeight: '700',
              color: textColor,
              lineHeight: '1.2',
              flex: '1',
              display: 'flex',
              alignItems: 'center'
            }}>
              {item.preview}
