          <>
            <div style={labelStyle}>{item.label}</div>
            <div style={{
              fontSize: '13px',
              fontWeight: '400',
              color: textColor,
              lineHeight: '1.4',
              flex: '1',
              display: 'flex',
              alignItems: 'center'
            }}>
              {item.preview}
            </div>
            <div style={{
              fontSize: `${fontSize - 1}px`,
              color: secondaryTextColor
            }}>
              {item.specs}
            </div>
          </>
        );

      case 'button':
        return (
          <>
            <div style={labelStyle}>{item.label}</div>
            <div style={{
              flex: '1',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}>
              <div style={{
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '10px 24px',
                borderRadius: '24px',
                fontSize: `${fontSize}px`,
                fontWeight: '500',
                backgroundColor: textColor,
                color: backgroundColor
              }}>
                {item.preview}
              </div>
            </div>
          </>
        );

      case 'box':
        return (
          <>
            <div style={labelStyle}>{item.label}</div>
            <div style={{
              flex: '1',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}>
              <div style={{
                width: '60px',
                height: '60px',
                backgroundColor: backgroundColor,
                borderRadius: '12px',
                border: `1px solid ${borderColor}`
              }} />
            </div>
          </>
        );

      case 'line':
        return (
          <>
            <div style={labelStyle}>{item.label}</div>
            <div style={{
              flex: '1',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}>
              <div style={{
                width: '80%',
                height: item.thickness,
                backgroundColor: textColor,
                borderRadius: '1px'
              }} />
            </div>
          </>
        );

      default:
        return null;
    }
  };

  return (
    <div className="branded-elements-bento" style={containerStyle}>
      {/* Header */}
      <div style={headerStyle}>
        <div style={titleStyle}>
          {sectionTitle}
          {showInfoIcon && (
            <span style={infoIconStyle} title="Branded design system elements">i</span>
          )}
        </div>
        {showSeeAll && (
          <a style={seeAllStyle} onClick={handleSeeAllClick}>
            {seeAllText}
          </a>
        )}
      </div>

      {/* Bento Grid */}
      <div style={bentoGridStyle}>
        {bentoItems.map((item) => (
          <div
            key={item.id}
            style={getCardStyle(item.id, item.gridArea)}
            onMouseEnter={() => setHoveredItem(item.id)}
            onMouseLeave={() => setHoveredItem(null)}
            onClick={() => handleItemClick(item.id)}
            onMouseDown={(e) => e.currentTarget.style.cursor = 'grabbing'}
            onMouseUp={(e) => e.currentTarget.style.cursor = 'grab'}
          >
            {renderContent(item)}
          </div>
        ))}
      </div>
    </div>
  );
}

