    alignItems: 'center',
    justifyContent: 'center',
    cursor: 'pointer',
    fontSize: '20px',
    color: textColor,
    transition: 'all 200ms ease-out',
    userSelect: 'none'
  });

  const indicatorsStyle = {
    display: 'flex',
    gap: '8px',
    justifyContent: 'center',
    marginTop: '20px'
  };

  const indicatorStyle = (isActive) => ({
    width: isActive ? '24px' : '8px',
    height: '8px',
    borderRadius: '4px',
    backgroundColor: isActive ? textColor : borderColor,
    cursor: 'pointer',
    transition: 'all 200ms ease-out'
  });

  const labelStyle = {
    position: 'absolute',
    top: '16px',
    left: '20px',
    fontSize: '11px',
    color: secondaryTextColor,
    fontWeight: '400',
    letterSpacing: '0.02em'
  };

  const renderContent = () => {
    switch (currentItem.type) {
      case 'heading':
        return (
          <>
            <div style={{
              fontSize: '48px',
              fontWeight: '700',
              color: textColor,
              lineHeight: '1.2',
              textAlign: 'center',
              marginBottom: '16px'
            }}>
              {currentItem.preview}
            </div>
            <div style={{
              fontSize: `${fontSize - 1}px`,
              color: secondaryTextColor
            }}>
              {currentItem.specs}
            </div>
          </>
        );

      case 'text':
        return (
          <>
            <div style={{
              fontSize: '16px',
              fontWeight: '400',
              color: textColor,
              lineHeight: '1.5',
              textAlign: 'center',
              maxWidth: '80%',
              marginBottom: '16px'
            }}>
              {currentItem.preview}
            </div>
            <div style={{
              fontSize: `${fontSize - 1}px`,
              color: secondaryTextColor
            }}>
              {currentItem.specs}
            </div>
          </>
        );

      case 'button':
        return (
          <div style={{
            display: 'inline-flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '12px 32px',
            borderRadius: '24px',
            fontSize: `${fontSize + 2}px`,
            fontWeight: '500',
            backgroundColor: textColor,
            color: backgroundColor,
            cursor: 'pointer'
          }}>
            {currentItem.preview}
          </div>
        );

      case 'box':
        return (
          <div style={{
            width: '120px',
            height: '120px',
            backgroundColor: backgroundColor,
            borderRadius: cornerRadius,
            border: `1px solid ${borderColor}`
          }} />
        );

      case 'line':
        return (
          <div style={{
            width: '200px',
            height: currentItem.thickness,
            backgroundColor: textColor,
            borderRadius: '1px'
          }} />
        );

      default:
        return null;
    }
  };

  return (
    <div className="branded-elements-carousel" style={containerStyle}>
      {/* Header */}
      <div style={headerStyle}>
        <div style={titleStyle}>
          {sectionTitle}
          {showInfoIcon && (
            <span style={infoIconStyle} title="Branded design system elements">i</span>
          )}
        </div>
        {showSeeAll && (
          <a style={seeAllStyle} onClick={handleSeeAllClick}>
            {seeAllText}
          </a>
        )}
      </div>

      {/* Carousel */}
      <div style={carouselContainerStyle}>
        <div style={cardStyle}>
          <div style={labelStyle}>{currentItem.label}</div>
          {renderContent()}
        </div>

        {/* Navigation Buttons */}
        <div
          style={navButtonStyle('left')}
          onClick={handlePrev}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = cardBackgroundColor;
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = backgroundColor;
          }}
        >
          ←
        </div>
        <div
          style={navButtonStyle('right')}
          onClick={handleNext}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = cardBackgroundColor;
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = backgroundColor;
          }}
        >
          →
        </div>
      </div>

      {/* Indicators */}
      <div style={indicatorsStyle}>
        {carouselItems.map((item, index) => (
          <div
            key={item.id}
            style={indicatorStyle(index === currentIndex)}
            onClick={() => setCurrentIndex(index)}
          />
        ))}
      </div>
    </div>
  );
}

