    gap: '8px'
  };

  const infoIconStyle = {
    width: '16px',
    height: '16px',
    borderRadius: '50%',
    border: `1px solid ${secondaryTextColor}`,
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '10px',
    color: secondaryTextColor,
    cursor: 'help'
  };

  const seeAllStyle = {
    color: linkColor,
    fontSize: `${fontSize}px`,
    fontWeight: '400',
    textDecoration: 'none',
    cursor: 'pointer'
  };

  const listContainerStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: itemSpacing
  };

  const getItemStyle = (itemId) => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '10px 12px',
    backgroundColor: hoveredItem === itemId ? hoverBackgroundColor : 'transparent',
    borderRadius: '6px',
    cursor: 'grab',
    userSelect: 'none',
    transition: 'all 150ms ease-out',
    border: `1px solid ${hoveredItem === itemId ? borderColor : 'transparent'}`
  });

  const leftSectionStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    flex: '1'
  };

  const iconStyle = {
    width: '32px',
    height: '32px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: hoverBackgroundColor,
    border: `1px solid ${borderColor}`,
    borderRadius: '6px',
    fontSize: '14px',
    fontWeight: '500',
    color: textColor,
    flexShrink: 0
  };

  const labelStyle = {
    fontSize: `${fontSize}px`,
    fontWeight: '400',
    color: textColor
  };

  const specsStyle = {
    fontSize: `${fontSize - 1}px`,
    color: secondaryTextColor,
    fontWeight: '400',
    marginLeft: 'auto',
    paddingLeft: '12px'
  };

  const previewStyle = (item) => {
    switch (item.type) {
      case 'heading':
        return {
          fontSize: '18px',
          fontWeight: '700',
          color: textColor,
          marginLeft: '12px'
        };
      case 'text':
        return {
          fontSize: '11px',
          fontWeight: '400',
          color: secondaryTextColor,
          marginLeft: '12px',
          maxWidth: '120px',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap'
        };
      case 'button':
        return {
          display: 'inline-flex',
          alignItems: 'center',
          padding: '4px 12px',
          borderRadius: '12px',
          fontSize: '10px',
          fontWeight: '500',
          backgroundColor: textColor,
          color: backgroundColor,
          marginLeft: '12px'
        };
      case 'box':
        return {
          width: '24px',
          height: '24px',
          backgroundColor: hoverBackgroundColor,
          border: `1px solid ${borderColor}`,
          borderRadius: '4px',
          marginLeft: '12px'
        };
      case 'line':
        return {
          width: '40px',
          height: '1px',
          backgroundColor: textColor,
          marginLeft: '12px'
        };
      default:
        return {};
    }
  };

  const renderPreview = (item) => {
    if (!showPreviews) return null;

    switch (item.type) {
      case 'heading':
        return <div style={previewStyle(item)}>Aa</div>;
      case 'text':
        return <div style={previewStyle(item)}>Sample text preview</div>;
      case 'button':
        return <div style={previewStyle(item)}>Btn</div>;
      case 'box':
        return <div style={previewStyle(item)} />;
      case 'line':
        return <div style={previewStyle(item)} />;
      default:
        return null;
    }
  };

  return (
    <div className="branded-elements-compact" style={containerStyle}>
      {/* Header */}
      <div style={headerStyle}>
        <div style={titleStyle}>
          {sectionTitle}
          {showInfoIcon && (
            <span style={infoIconStyle} title="Branded design system elements">i</span>
          )}
        </div>
        {showSeeAll && (
          <a style={seeAllStyle} onClick={handleSeeAllClick}>
            {seeAllText}
          </a>
        )}
      </div>

      {/* Compact List */}
      <div style={listContainerStyle}>
        {listItems.map((item) => (
          <div
            key={item.id}
            style={getItemStyle(item.id)}
            onMouseEnter={() => setHoveredItem(item.id)}
            onMouseLeave={() => setHoveredItem(null)}
            onClick={() => handleItemClick(item.id)}
            onMouseDown={(e) => e.currentTarget.style.cursor = 'grabbing'}
            onMouseUp={(e) => e.currentTarget.style.cursor = 'grab'}
          >
            <div style={leftSectionStyle}>
              <div style={iconStyle}>{item.icon}</div>
              <div style={labelStyle}>{item.label}</div>
              {renderPreview(item)}
            </div>
            <div style={specsStyle}>{item.specs}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

