  const cornerRadius = config?.cornerRadius || '8px';
  const cardPadding = config?.cardPadding || '16px';
  const gridGap = config?.gridGap || '12px';

  // Grid items with scaled content for 1:1 cells
  const gridItems = [
    {
      id: 'heading-2',
      type: 'heading',
      label: 'Heading 2',
      preview: 'Fresh Perspectives',
      specs: '64/72 px'
    },
    {
      id: 'paragraph-2',
      type: 'text',
      label: 'Paragraph 2',
      preview: 'This is the space to introduce the Services section.',
      specs: '16/20 px'
    },
    {
      id: 'primary-button',
      type: 'button',
      label: 'Primary',
      preview: 'Button'
    },
    {
      id: 'box-1',
      type: 'box',
      label: 'Box 1',
      preview: null
    },
    {
      id: 'line-1',
      type: 'line',
      label: 'Line 1',
      thickness: '1px',
      specs: '1px'
    }
  ];

  const handleItemClick = (itemId) => {
    console.log(`Clicked: ${itemId}`);
  };

  const handleSeeAllClick = () => {
    console.log('See All clicked - navigate to drill-in view');
  };

  const containerStyle = {
    backgroundColor,
    padding: '24px',
    fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
    color: textColor,
    fontSize: `${fontSize}px`,
    fontWeight
  };

  const headerStyle = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
