          {item.preview}
        </div>
      </div>
      <div style={{
        fontSize: '11px',
        color: secondaryTextColor,
        fontWeight: '400',
        letterSpacing: '0.02em',
        marginTop: '8px',
        paddingLeft: '4px'
      }}>
        Primary
      </div>
    </div>
  );

  const renderBox = (item) => (
    <div key={item.id}>
      <div
        style={getCardStyle(item.id)}
        onMouseEnter={() => setHoveredItem(item.id)}
        onMouseLeave={() => setHoveredItem(null)}
        onClick={() => handleItemClick(item.id)}
        onMouseDown={(e) => e.currentTarget.style.cursor = 'grabbing'}
        onMouseUp={(e) => e.currentTarget.style.cursor = 'grab'}
      >
        <div style={{
          height: '64px',
          backgroundColor: hoverBackgroundColor,
          borderRadius: cornerRadius,
          border: `1px solid ${borderColor}`
        }} />
      </div>
      <div style={{
        fontSize: '11px',
        color: secondaryTextColor,
        fontWeight: '400',
        letterSpacing: '0.02em',
        marginTop: '8px',
        paddingLeft: '4px'
      }}>
        Box 1
      </div>
    </div>
  );

  const renderLine = (item) => (
    <div key={item.id}>
      <div
        style={getCardStyle(item.id)}
        onMouseEnter={() => setHoveredItem(item.id)}
        onMouseLeave={() => setHoveredItem(null)}
        onClick={() => handleItemClick(item.id)}
        onMouseDown={(e) => e.currentTarget.style.cursor = 'grabbing'}
        onMouseUp={(e) => e.currentTarget.style.cursor = 'grab'}
      >
        <div style={{
          width: '100%',
          height: item.thickness,
          backgroundColor: textColor,
          borderRadius: '1px'
        }} />
      </div>
      <div style={{
        fontSize: '11px',
        color: secondaryTextColor,
        fontWeight: '400',
        letterSpacing: '0.02em',
        marginTop: '8px',
        paddingLeft: '4px'
      }}>
        Line 1 • {item.thickness}
      </div>
    </div>
  );

  const renderItem = (item) => {
    switch (item.type) {
      case 'heading':
        return renderHeading(item);
      case 'text':
        return renderText(item);
      case 'button':
        return renderButton(item);
      case 'box':
        return renderBox(item);
      case 'line':
        return renderLine(item);
      default:
        return null;
    }
  };

  return (
    <div className="branded-elements-lobby" style={containerStyle}>
      {/* Header */}
      <div style={headerStyle}>
        <div style={titleStyle}>
          {sectionTitle}
          {showInfoIcon && (
            <span style={infoIconStyle} title="Branded design system elements">i</span>
          )}
        </div>
        {showSeeAll && (
          <a 
            style={seeAllStyle}
            onMouseEnter={(e) => e.currentTarget.style.opacity = '1'}
            onMouseLeave={(e) => e.currentTarget.style.opacity = '0.8'}
            onClick={handleSeeAllClick}
          >
            {seeAllText}
          </a>
        )}
      </div>

      {/* Preview Items */}
      <div>
        {/* Heading + Paragraph in a row */}
        <div style={{
          display: 'grid',
