  };

  const handleCellClick = (row, col) => {
    const key = `${row}-${col}`;
    console.log(`Clicked: ${key}`, matrixData[key]);
  };

  const containerStyle = {
    backgroundColor,
    padding: '24px',
    fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
