    color: '#FFFFFF',
    fontSize: `${fontSize}px`,
    fontWeight: '500',
    borderBottom: `1px solid ${borderColor}`,
    whiteSpace: 'nowrap'
  };

  const getCellStyle = (key) => ({
    padding: '20px',
    backgroundColor: hoveredCell === key ? '#FFFFFF' : cellBackgroundColor,
    border: `1px solid ${borderColor}`,
